package fixtures

import (
	"slices"
	"sync"
	"time"
)

// A "later" fixture is a second export of the same workspace, taken some
// days after its base: everything the base holds, plus what people did in
// between. The pair exists to test incremental passes, which import from
// the later export only what the base's import did not.
//
// "small-later" follows "small" and "medium-later" follows "medium". The
// base part of a later fixture is generated by the base's own builder, so
// the two exports agree byte for byte on everything that did not change.
// What changed is listed in LaterFixtureFacts.

// LaterSuffix is what the name of a later fixture adds to its base's.
const LaterSuffix = "-later"

// LaterOf returns the name of the later export of a base fixture.
func LaterOf(base string) string { return base + LaterSuffix }

// LaterNames returns the later fixtures, in the order of their bases.
func LaterNames() []string { return []string{LaterOf("small"), LaterOf("medium")} }

// LaterFixtureFacts is the ground truth about what a later export adds to,
// and changes in, its base. Counts are of well-formed messages.
type LaterFixtureFacts struct {
	// NewMessages is every message the base does not have, replies
	// included. NewReplies are the replies among them, and RepliesToOld the
	// replies whose thread's first message is in the base.
	NewMessages  int
	NewReplies   int
	RepliesToOld int
	// LateArrivals are new messages dated inside the base's history. Each
	// shares a millisecond with a message of the base.
	LateArrivals int
	// NewFiles are the files attached to new messages.
	NewFiles int
	// NewChannels are conversations the base does not list; NewUsers the
	// people.
	NewChannels int
	NewUsers    int
	// Edited are messages of the base whose text and "edited" marker
	// changed; Deleted are messages of the base the later export no longer
	// has.
	Edited  int
	Deleted int
	// NewDMMessages are the new messages that are in direct messages and
	// group DMs. They are part of NewMessages.
	NewDMMessages int
	// EditedTS and DeletedTS name them, by channel ID.
	EditedTS  map[string][]string
	DeletedTS map[string][]string
	// QuietChannel is a public channel of the base in which nothing new
	// was said; empty when every channel has new messages.
	QuietChannel string
	// NewChannel is the name of the channel the base does not have.
	NewChannel string
}

func init() {
	for base, build := range map[string]func() *builder{"small": buildSmall, "medium": buildMedium} {
		name := LaterOf(base)
		builders[name] = func() *builder {
			b := build()
			b.laterFacts = b.later()
			return b
		}
		cache[name] = sync.OnceValue(func() *built { return builders[name]().finish() })
	}
}

// LaterFacts returns what the named later fixture adds to its base. It
// panics on a name that is not a later fixture.
func LaterFacts(name string) LaterFixtureFacts {
	f := mustGet(name).later
	if f == nil {
		panic("fixtures: " + name + " is not a later fixture")
	}
	return *f
}

// later extends a finished base workspace with a few more days of history
// and returns what it added. It draws from the builder's own random
// sequence after the base has taken what it needs, so the base part is
// unchanged and the result is deterministic.
func (b *builder) later() *LaterFixtureFacts {
	f := &LaterFixtureFacts{EditedTS: map[string][]string{}, DeletedTS: map[string][]string{}}

	// The base's channels and where its history ends.
	base := slices.Clone(b.channels)
	var last stamp
	for _, c := range base {
		for _, e := range c.entries {
			last = max(last, e.at)
		}
	}
	start := at(time.UnixMicro(int64(last)).UTC().Truncate(24*time.Hour).AddDate(0, 0, 1).Add(9 * time.Hour))

	// Two people join. One has a Microsoft 365 account, one does not.
	joined := b.addUser(userSpec{first: "Priya", last: "Raman"})
	contractor := b.addUser(userSpec{first: "Otto", last: "Lind", unmapped: true})
	f.NewUsers = 2

	var named, private, dms []*channel
	for _, c := range base {
		switch {
		case len(c.entries) == 0 || c.archived:
		case c.kind == "public":
			named = append(named, c)
		case c.kind == "private":
			private = append(private, c)
		default:
			dms = append(dms, c)
		}
	}
	if len(named) > 0 {
		named[0].members = append(named[0].members, joined, contractor)
	}
	// The last public channel went quiet: nothing new is said in it. A
	// pass has nothing to import into it and must leave it alone.
	if len(named) > 2 {
		f.QuietChannel = named[len(named)-1].name
		named = named[:len(named)-1]
	}

	count := func(c *channel, m *message) {
		f.NewMessages++
		if m.ThreadTS != "" && m.ThreadTS != m.TS {
			f.NewReplies++
		}
		f.NewFiles += len(m.Files)
		if c.kind == "dm" || c.kind == "mpim" {
			f.NewDMMessages++
		}
	}
	say := func(c *channel, t stamp, u *user) *message {
		m := c.post(t, b.richBody(by(u, &message{}), c.members, named))
		count(c, m)
		return m
	}

	// Three more days of conversation in every channel that had any.
	for d := range 3 {
		day := start.add(time.Duration(d) * 24 * time.Hour)
		for ci, c := range append(slices.Clone(named), private...) {
			for i := range 2 + (ci+d)%3 {
				t := day.add(time.Duration(i*53+ci*11)*time.Minute + time.Duration(b.rng.IntN(50_000_000))*time.Microsecond)
				u := c.members[(d+i+ci)%len(c.members)]
				if len(named) > 0 && c == named[0] && i == 0 {
					u = []*user{joined, contractor}[d%2]
				}
				m := c.post(t, b.richBody(by(u, &message{}), c.members, named))
				if (ci+d+i)%5 == 0 {
					m.Files = []*file{b.hostedFile(b.byID[m.User], m.at, "notes "+m.at.day()+".txt", "text/plain", "text", "Plain Text", int64(2_000+b.rng.IntN(40_000)))}
					m.Upload = true
				}
				count(c, m)
			}
		}
	}

	// New replies in threads the base already has, and under messages of
	// the base that had no thread yet: the case Microsoft's own tool
	// misses.
	for ci, c := range append(slices.Clone(named), private...) {
		if ci >= 4 {
			break
		}
		var parent, lone *message
		for _, e := range c.entries {
			m := e.msg
			if m == nil || e.at >= start || m.Subtype != "" || m.User == "" {
				continue
			}
			switch {
			case m.ThreadTS == m.TS && parent == nil:
				parent = m
			case m.ThreadTS == "" && lone == nil:
				lone = m
			}
		}
		for i, p := range []*message{parent, lone} {
			if p == nil {
				continue
			}
			for n := range 2 {
				r := by(c.members[(ci+i+n)%len(c.members)], &message{})
				b.rich(r, section(tx(b.sentence())))
				m := c.reply(p, start.add(time.Duration(30+ci*7+i*3+n)*time.Minute), r, false)
				count(c, m)
				f.RepliesToOld++
			}
		}
	}

	// A new thread, begun and answered after the base.
	if len(named) > 1 {
		c := named[1]
		p := say(c, start.add(26*time.Hour), c.members[0])
		for n := range 3 {
			r := by(c.members[(n+1)%len(c.members)], &message{})
			b.rich(r, section(tx(b.sentence())))
			count(c, c.reply(p, p.at.add(time.Duration(n+1)*5*time.Minute), r, false))
		}
	}

	// A channel that did not exist when the base was exported.
	if len(named) > 0 {
		c := b.addChannel("public", "launch-review", joined, append([]*user{joined}, named[0].members[:min(4, len(named[0].members))]...)...)
		c.created = start.add(-2 * time.Hour)
		c.purpose = "Review of the launch"
		f.NewChannels++
		f.NewChannel = c.name
		for i := range 6 {
			say(c, start.add(time.Duration(i*90)*time.Minute), c.members[i%len(c.members)])
		}
	}

	// A message that the base did not have although it is dated inside the
	// base's history (a message from a shared channel that arrived late, or
	// one restored after the first export), in the very millisecond of a
	// message the base did have.
	if len(named) > 0 {
		c := named[0]
		for _, e := range c.entries {
			if e.msg == nil || e.at >= start || e.msg.Subtype != "" {
				continue
			}
			m := c.postExact(e.at+400, b.richBody(by(c.members[1%len(c.members)], &message{}), c.members, named))
			count(c, m)
			f.LateArrivals++
			break
		}
	}

	// Direct messages carry on too.
	for i, c := range dms {
		if i >= 2 || len(c.members) < 2 {
			continue
		}
		for n := range 2 {
			m := c.post(start.add(time.Duration(200+i*17+n*9)*time.Minute), by(c.members[n%len(c.members)], &message{Text: "A later direct message."}))
			count(c, m)
		}
	}

	// One message of the base is edited and one is deleted, per channel,
	// in the first two channels. Neither can be carried into Teams.
	for ci, c := range named {
		if ci >= 2 {
			break
		}
		var plain []int
		for i, e := range c.entries {
			m := e.msg
			if m != nil && e.at < start && m.Subtype == "" && m.ThreadTS == "" && len(m.Files) == 0 && m.Edited == nil && m.User != "" {
				plain = append(plain, i)
			}
		}
		if len(plain) < 4 {
			continue
		}
		ed := c.entries[plain[len(plain)/2]].msg
		ed.Text += " (corrected)"
		ed.Blocks = nil
		ed.Edited = &edited{User: ed.User, TS: start.add(time.Duration(ci+1) * time.Hour).String()}
		f.Edited++
		f.EditedTS[c.id] = append(f.EditedTS[c.id], ed.TS)

		gone := plain[len(plain)/3]
		f.DeletedTS[c.id] = append(f.DeletedTS[c.id], c.entries[gone].msg.TS)
		c.entries = slices.Delete(c.entries, gone, gone+1)
		f.Deleted++
	}
	return f
}
